#define MAXNAME			1000
#define KV_TO_mV		1000000
/* NSSOC resistor provenance v1. Diagnostic only; numerical objects are read-only.
 * Inserted into qualified ResPrint.c. No resistor struct/ABI change.
 * Names are hex-encoded original bytes. Object addresses are process-local
 * observation keys, NEVER stable identities or proof of physical ownership.
 */
#include <stdlib.h>
#include <errno.h>

static FILE *mrpFile = NULL;
static int mrpState = 0; /* 0 unchecked, 1 active, 2 disabled, -1 failed */
static unsigned long long mrpSeq = 0, mrpEpoch = 0;
static int mrpInNet = 0;

static void mrpFailure(const char *where)
{
    int saved = errno;
    mrpState = -1;
    TxError("NSSOC_RESISTOR_TRACE_ERROR %s errno=%d\n", where, saved);
}
static void mrpHex(const char *value)
{
    const unsigned char *p;
    if (value == NULL) { fputs("null", mrpFile); return; }
    fputc('"', mrpFile);
    for (p = (const unsigned char *)value; *p; p++)
        fprintf(mrpFile, "%02x", (unsigned int)*p);
    fputc('"', mrpFile);
}
static void mrpFinish(void)
{
    fputs("}\n", mrpFile);
    if (ferror(mrpFile) || fflush(mrpFile) != 0)
        mrpFailure("write_or_flush");
}
static void mrpClose(void)
{
    if (mrpFile == NULL) return;
    if (mrpState == 1)
    {
        fprintf(mrpFile, "{\"schema\":1,\"event\":\"trace_end\","
                "\"records_before_footer\":%llu,\"epochs\":%llu,"
                "\"net_still_open\":%s,\"physical_ownership_proved\":false",
                mrpSeq, mrpEpoch, mrpInNet ? "true" : "false");
        mrpFinish();
    }
    if (fclose(mrpFile) != 0) mrpFailure("close");
    mrpFile = NULL;
}
static int mrpReady(void)
{
    const char *path;
    if (mrpState != 0) return mrpState == 1;
    path = getenv("NSSOC_MAGIC_RESISTOR_TRACE");
    if (path == NULL || *path == '\0') { mrpState = 2; return 0; }
    /* Linux/glibc exclusive creation: never truncate an earlier trace. */
    mrpFile = fopen(path, "wx");
    if (mrpFile == NULL) { mrpFailure("exclusive_open"); return 0; }
    mrpState = 1;
    if (atexit(mrpClose) != 0) { mrpFailure("atexit"); return 0; }
    fputs("{\"schema\":1,\"event\":\"trace_start\","
          "\"magic_upstream\":\"fd12c39c37f26a0fe6e04698b1011e31b8bd3229\","
          "\"instrumentation\":\"nssoc_resistor_provenance_v1\","
          "\"names\":\"hex_original_bytes\","
          "\"pointer_scope\":\"this_process_ordered_creation_epoch_only\","
          "\"resistor_footprint_is_not_inferred\":true", mrpFile);
    mrpFinish();
    return mrpState == 1;
}
static int mrpStart(const char *event)
{
    if (!mrpReady()) return 0;
    fprintf(mrpFile, "{\"schema\":1,\"seq\":%llu,\"epoch\":%llu,"
            "\"event\":\"%s\"", ++mrpSeq, mrpEpoch, event);
    return 1;
}
static void mrpRect(const Rect *rect)
{
    if (rect == NULL) { fputs("null", mrpFile); return; }
    fprintf(mrpFile, "[%d,%d,%d,%d]", rect->r_xbot, rect->r_ybot,
            rect->r_xtop, rect->r_ytop);
}
static void mrpTile(const Tile *tile)
{
    if (tile == NULL) { fputs("null", mrpFile); return; }
    fprintf(mrpFile, "{\"bbox\":[%d,%d,%d,%d],"
            "\"exact_type\":%u,\"split\":%s,\"split_direction\":%d,"
            "\"left_type\":%u,\"right_type\":%u}",
            LEFT(tile), BOTTOM(tile), RIGHT(tile), TOP(tile),
            (unsigned int)TiGetTypeExact(tile),
            IsSplit(tile) ? "true" : "false", SplitDirection(tile),
            (unsigned int)TiGetLeftType(tile), (unsigned int)TiGetRightType(tile));
}
static void mrpNode(const resNode *node)
{
    if (node == NULL) { fputs("null", mrpFile); return; }
    fprintf(mrpFile, "{\"address\":\"%p\",\"xy\":[%d,%d],"
            "\"status\":%d,\"why\":%u,\"name_hex\":",
            (const void *)node, node->rn_loc.p_x, node->rn_loc.p_y,
            node->rn_status, node->rn_why);
    mrpHex(node->rn_name);
    fputc('}', mrpFile);
}
static void mrpResistor(const resResistor *resistor)
{
    int valid = resistor->rr_tt >= 0 && resistor->rr_tt < DBNumTypes;
    fprintf(mrpFile, ",\"resistor_address\":\"%p\","
            "\"rr_value_milliohms_hex\":\"%a\",\"rr_status\":%d,"
            "\"rr_tt\":%d,\"rr_width_raw\":%d,\"rr_cl_raw\":%d,"
            "\"type_index_valid\":%s,\"material_name_hex\":",
            (const void *)resistor, (double)resistor->rr_value,
            resistor->rr_status, (int)resistor->rr_tt,
            resistor->rr_width, resistor->rr_cl, valid ? "true" : "false");
    mrpHex(valid ? DBTypeLongNameTbl[resistor->rr_tt] : NULL);
    if (valid)
        fprintf(mrpFile, ",\"is_contact\":%s,\"sheet_resist_raw\":%d,"
                "\"via_resist_raw\":%d",
                DBIsContact(resistor->rr_tt) ? "true" : "false",
                ExtCurStyle->exts_sheetResist[resistor->rr_tt],
                ExtCurStyle->exts_viaResist[resistor->rr_tt]);
    fprintf(mrpFile, ",\"resist_scale\":%d,\"node1\":",
            ExtCurStyle->exts_resistScale);
    mrpNode(resistor->rr_node[0]);
    fputs(",\"node2\":", mrpFile);
    mrpNode(resistor->rr_node[1]);
}
void ResPhysicalTraceBegin(const char *net, const char *cell)
{
    if (!mrpReady()) return;
    if (mrpInNet) { mrpFailure("nested_net"); return; }
    mrpEpoch++;
    mrpInNet = 1;
    if (!mrpStart("net_begin")) return;
    fputs(",\"net_name_hex\":", mrpFile); mrpHex(net);
    fputs(",\"cell_argument_hex\":", mrpFile); mrpHex(cell);
    fprintf(mrpFile, ",\"options\":%d,\"cif_output_um_per_internal_hex\":\"%a\","
            "\"resist_scale\":%d,\"physical_ownership_proved\":false",
            ResOptionsFlags, (double)CIFGetOutputScale(1000),
            ExtCurStyle->exts_resistScale);
    mrpFinish();
}
void ResPhysicalTraceEnd(void)
{
    if (!mrpReady() || !mrpInNet) return;
    if (mrpStart("net_end")) mrpFinish();
    mrpInNet = 0;
}
void ResPhysicalTraceTile(const resResistor *resistor, const Tile *tile,
                         const Breakpoint *first, const Breakpoint *second,
                         const char *axis)
{
    if (!mrpStart("create_tile")) return;
    mrpResistor(resistor);
    fprintf(mrpFile, ",\"constructor_axis\":\"%s\",\"tile\":", axis);
    mrpTile(tile);
    fprintf(mrpFile, ",\"break1_xy\":[%d,%d],\"break2_xy\":[%d,%d],"
            "\"break1_contact_rect\":", first->br_loc.p_x, first->br_loc.p_y,
            second->br_loc.p_x, second->br_loc.p_y);
    mrpRect(first->br_crect);
    fputs(",\"break2_contact_rect\":", mrpFile); mrpRect(second->br_crect);
    fputs(",\"geometry_semantics\":\"creation_tile_and_break_interval_only\","
          "\"final_footprint_proved\":false", mrpFile);
    mrpFinish();
}
void ResPhysicalTraceContact(const resResistor *resistor,
                            const ResContactPoint *contact, int index,
                            int minside, int viawidth_current, int spacing,
                            int border, int cscale, int squaresx, int squaresy)
{
    if (!mrpStart("create_contact")) return;
    mrpResistor(resistor);
    fprintf(mrpFile, ",\"contact_type\":%d,\"contact_center\":[%d,%d],"
            "\"contact_width_raw\":%d,\"contact_height_raw\":%d,"
            "\"contact_layers\":%d,\"layer_pair_index\":%d,\"contact_rect\":",
            (int)contact->cp_type, contact->cp_center.p_x,
            contact->cp_center.p_y, contact->cp_width, contact->cp_height,
            contact->cp_currentcontact, index);
    mrpRect(&contact->cp_rect);
    fputs(",\"lower_constructor_tile\":", mrpFile);
    mrpTile(contact->cp_tile[index - 1]);
    fputs(",\"upper_constructor_tile\":", mrpFile);
    mrpTile(contact->cp_tile[index]);
    fprintf(mrpFile, ",\"minside\":%d,\"viawidth_current\":%d,"
            "\"spacing\":%d,\"border\":%d,\"cif_scale_factor\":%d,"
            "\"squares_x\":%d,\"squares_y\":%d,"
            "\"geometry_semantics\":\"contact_region_not_individual_cut_polygons\","
            "\"final_footprint_proved\":false",
            minside, viawidth_current, spacing, border, cscale, squaresx, squaresy);
    mrpFinish();
}
void ResPhysicalTraceSnapshot(const char *phase, const resResistor *list)
{
    unsigned long long count = 0;
    const resResistor *resistor;
    if (!mrpStart("snapshot_begin")) return;
    fprintf(mrpFile, ",\"phase\":\"%s\"", phase); mrpFinish();
    for (resistor = list; resistor != NULL; resistor = resistor->rr_nextResistor)
    {
        if (!mrpStart("snapshot_resistor")) return;
        fprintf(mrpFile, ",\"phase\":\"%s\",\"index\":%llu", phase, count++);
        mrpResistor(resistor);
        mrpFinish();
    }
    if (!mrpStart("snapshot_end")) return;
    fprintf(mrpFile, ",\"phase\":\"%s\",\"count\":%llu", phase, count);
    mrpFinish();
}
void ResPhysicalTraceOutput(const resResistor *resistor, const char *net)
{
    if (!mrpStart("emitted_resistor")) return;
    mrpResistor(resistor);
    fputs(",\"writer_net_hex\":", mrpFile); mrpHex(net);
    /* Reuse the exact original float expression and %g presentation.
     * Original fprintf remains untouched; this is an additional observation. */
    fprintf(mrpFile, ",\"ext_value_token\":\"%g\",\"final_footprint_proved\":false",
            resistor->rr_value / (float)ExtCurStyle->exts_resistScale);
    mrpFinish();
}
void ResPhysicalTraceOrphan(const char *first, const char *second)
{
    if (!mrpStart("emitted_orphan_zero")) return;
    fputs(",\"node1_name_hex\":", mrpFile); mrpHex(first);
    fputs(",\"node2_name_hex\":", mrpFile); mrpHex(second);
    fputs(",\"ext_value_token\":\"0.0\",\"resistor_address\":null,"
          "\"material_unknown\":true,\"final_footprint_proved\":false", mrpFile);
    mrpFinish();
}

/*
 *-------------------------------------------------------------------------
 *
 * ResPrintExtRes-- Print resistor network to output file.
 *
 * Results:none
 *
 * Side Effects:prints network.
 *
 *-------------------------------------------------------------------------
 */

void
ResPrintExtRes(outextfile, resistors, nodename)
    FILE	*outextfile;
    resResistor *resistors;
    char	*nodename;

{
    int	        nodenum=0;
    char	newname[MAXNAME];
    HashEntry  *entry;
    ResExtNode *node;

    for (; resistors != NULL; resistors = resistors->rr_nextResistor)
    {
	/*
	 * These names shouldn't be null; they should either be set by
	 * the device name or by the node printing routine.  This
	 * code is included in case the resistor network is printed
	 * before the nodes.
	 */

	if (resistors->rr_connection1->rn_name == NULL)
	{
     	    (void)sprintf(newname, "%s%s%d", nodename, ".r", nodenum++);
     	    entry = HashFind(&ResNodeTable, newname);
	    node = ResExtInitNode(entry);
	    resistors->rr_connection1->rn_name = node->name;
	    node->oldname = nodename;
	}
	if (resistors->rr_connection2->rn_name == NULL)
	{
     	    (void)sprintf(newname, "%s%s%d", nodename, ".r", nodenum++);
     	    entry = HashFind(&ResNodeTable, newname);
	    node = ResExtInitNode(entry);
	    resistors->rr_connection2->rn_name = node->name;
	    node->oldname = nodename;
	}
	if (ResOptionsFlags & ResOpt_DoExtFile)
	{
     	    fprintf(outextfile, "resist \"%s\" \"%s\" %g\n",
		    resistors->rr_connection1->rn_name,
		    resistors->rr_connection2->rn_name,
		    resistors->rr_value / (float)ExtCurStyle->exts_resistScale);
	    ResPhysicalTraceOutput(resistors, nodename);
	}
    }
}

/*
 *-------------------------------------------------------------------------
 *
 * ResPrintExtDev-- Print out all devices that have had at least
 *	one terminal changed.
 *
 * Results:none
 *
 * Side Effects:prints device lines to output file
 *
 *-------------------------------------------------------------------------
 */

void
ResPrintExtDev(outextfile, devices)
    FILE	*outextfile;
    RDev	*devices;
{
    char *subsName;
    ExtDevice *devptr, *devtest;

    for (; devices != NULL; devices = devices->nextDev)
    {
	if (devices->status & TRUE)
	{
	    if (ResOptionsFlags & ResOpt_DoExtFile)
	    {
		devptr = devices->rs_devptr;
		subsName = devptr->exts_deviceSubstrateName;

#ifdef MAGIC_WRAPPER
		/* Substrate variable name substitution */
		if (subsName && subsName[0] == '$' && subsName[1] != '$')
		{
		    char *varsub = (char *)Tcl_GetVar(magicinterp, &subsName[1],
				TCL_GLOBAL_ONLY);
		    if (varsub != NULL) subsName = varsub;
		}
#endif
		/* Output according to device type and class. */
		/* Code largely matches what's in ExtBasic.c extOutputDevices() */

		if (devptr->exts_deviceClass != DEV_FET)
		    fprintf(outextfile,"device ");

		fprintf(outextfile,"%s %s %d %d %d %d ",
			extDevTable[(unsigned char)devptr->exts_deviceClass],
			devptr->exts_deviceName,
			devices->layout->rd_inside.r_ll.p_x,
			devices->layout->rd_inside.r_ll.p_y,
			devices->layout->rd_inside.r_ll.p_x + 1,
			devices->layout->rd_inside.r_ll.p_y + 1);

		switch (devptr->exts_deviceClass)
		{
		    case DEV_FET:
			fprintf(outextfile," %d %d",
				devices->layout->rd_area,
				devices->layout->rd_perim);
			break;

		    case DEV_MOSFET:
		    case DEV_ASYMMETRIC:
		    case DEV_BJT:
			fprintf(outextfile," %d %d",
				devices->layout->rd_length,
				devices->layout->rd_width);
			break;
		}

		if (devices->subs != NULL)
		    fprintf(outextfile, " \"%s\"", devices->subs->name);
		else if (subsName != NULL)
		    fprintf(outextfile, " \"%s\"", subsName);
		else
		    fprintf(outextfile, " \"None\"");

		if (devices->gate != NULL)
		    fprintf(outextfile, " \"%s\" %d %s",
			    devices->gate->name,
			    devices->layout->rd_length * 2,
			    (*devices->rs_gattr == '\0') ? "0" : devices->rs_gattr);

		if (devices->source != NULL)
		    fprintf(outextfile, " \"%s\" %d %s",
			    devices->source->name,
			    devices->layout->rd_width,
			    (*devices->rs_sattr == '\0') ? "0" : devices->rs_sattr);

		/* Don't write drain values for 2-terminal devices */
		if (devptr->exts_deviceSDCount > 1)
		    if (devices->drain != NULL)
		    	fprintf(outextfile, " \"%s\" %d %s",
				devices->drain->name,
				devices->layout->rd_width,
				(*devices->rs_dattr == '\0') ? "0" : devices->rs_dattr);

		fprintf(outextfile, "\n");
	    }
	}
    }
}


/*
 *-------------------------------------------------------------------------
 *
 * ResPrintExtNode-- Prints out all the nodes in the extracted net.
 *
 * Results:none
 *
 * Side Effects: Prints out extracted net. It may add new nodes to the
 *	node hash table.
 *
 *-------------------------------------------------------------------------
 */

void
ResPrintExtNode(outextfile, nodelist, node)
	FILE	*outextfile;
	resNode	*nodelist;
	ResExtNode *node;
{
    char       *nodename = node->name;
    int		nodenum = 0;
    char	newname[MAXNAME+32], tmpname[MAXNAME], *cp;
    HashEntry  *entry;
    ResExtNode *newnode;
    bool	DoKillNode = TRUE;
    bool	NeedFix = FALSE;
    resNode	*snode;

    /* If any of the subnode names match the original node name, then	*/
    /* we don't want to rip out that node with a "killnode" statement.	*/

    for (snode = nodelist; snode != NULL; snode = snode->rn_more)
    {
	if (snode->rn_name != NULL)
	    if (!strcmp(snode->rn_name, nodename))
	    {
		DoKillNode = FALSE;
		break;
	    }
    }

    /* If any device terminal failed to extract for any reason, then	*/
    /* this node cannot be killed.  If it is already marked for killing	*/
    /* then there are no connections from the node to any of its sub-	*/
    /* nodes, so create one an flag a warning.  Note that this		*/
    /* condition indicates a fundamental underlying error in device	*/
    /* extraction, but this prevents magic from generating an invalid	*/
    /* netlist.								*/

    if (node->status & DONTKILL)
	if (DoKillNode == TRUE)
	{
	    DoKillNode = FALSE;
	    NeedFix = TRUE;
	}

    if ((ResOptionsFlags & ResOpt_DoExtFile) && DoKillNode)
        fprintf(outextfile, "killnode \"%s\"\n", nodename);

    /* A retained original name keeps its NODE ground C in ext2spice.
     * This successful replacement network already distributes that intrinsic
     * C through its rnodes. Retire only the original intrinsic contribution
     * with the native subcap adjustment; do not subtract coupling C, kill a
     * retained port, or change repeated-rnode additive semantics.
     */
    if ((ResOptionsFlags & ResOpt_DoExtFile) && !DoKillNode && !NeedFix
            && nodelist != NULL && node->intrinsic_capacitance != 0.0)
        fprintf(outextfile, "subcap \"%s\" %.17g\n", nodename,
                -node->intrinsic_capacitance);

    /* Create "rnode" entries for each subnode */

    for (snode = nodelist; snode != NULL; snode = snode->rn_more)
    {
	if (snode->rn_name == NULL)
	{
	    (void)sprintf(tmpname,"%s",nodename);

	    cp = tmpname + strlen(tmpname) - 1;
            if (*cp == '!' || *cp == '#') *cp = '\0';

     	    (void)sprintf(newname, "%s%s%d", tmpname, ".n", nodenum++);
     	    entry = HashFind(&ResNodeTable, newname);
	    newnode = ResExtInitNode(entry);
	    snode->rn_name = newnode->name;
	    newnode->oldname = nodename;
	}

	if (ResOptionsFlags & ResOpt_DoExtFile)
	{
	    /* rnode name R C x y  type (R is always 0) */
     	    fprintf(outextfile, "rnode \"%s\" 0 %.17g %d %d %d\n",
		    snode->rn_name,
		    (snode->rn_float.rn_area / ExtCurStyle->exts_capScale),
		    snode->rn_loc.p_x,
		    snode->rn_loc.p_y,
		    /* the following is TEMPORARILY set to 0 */
		    0);
	}
    }

    if (NeedFix)
    {
	if (nodelist == NULL)
	{
	    TxError("Error:  Orphaned node \"%s\" not output.\n",
			node->name);
	    return;
	}

	/* Patch up the output netlist for an orphaned node by
	 * creating a zero-valued resistance between it and the
	 * first subnode (arbitrary connection).  Flag a warning.
	 */
	fprintf(outextfile, "resist \"%s\" \"%s\" 0.0\n",
		node->name, nodelist->rn_name);
	ResPhysicalTraceOrphan(node->name, nodelist->rn_name);
	TxError("Warning:  Orphaned node \"%s\" arbitrarily attached to \"%s\"\n",
		node->name, nodelist->rn_name);
    }
}

/*
 *-------------------------------------------------------------------------
 *
 * ResPrintStats -- Prints out the node name, the number of devices,
 *	and the number of nodes for each net added.  Also keeps a running
 *	track of the totals.
 *
 * Results:
 *
 * Side Effects:
 *
 *-------------------------------------------------------------------------
 */

void
ResPrintStats(resisdata, name)
    ResisData	*resisdata;
    char	*name;
{
    static int	totalnets = 0, totalnodes = 0, totalresistors = 0;
    int nodes, resistors;
    resNode	*node;
    resResistor *res;

    if (resisdata == NULL)
    {
     	  TxError("nets:%d nodes:%d resistors:%d\n",
	  	  totalnets, totalnodes, totalresistors);
	totalnets = 0;
	totalnodes = 0;
	totalresistors = 0;
	return;
    }
    nodes = 0;
    resistors = 0;
    totalnets++;
    for (node = ResNodeList; node != NULL; node=node->rn_more)

    {
     	nodes++;
	totalnodes++;
    }
    for (res = ResResList; res != NULL; res=res->rr_nextResistor)
    {
     	resistors++;
	totalresistors++;
    }
    TxError("%s %d %d\n", name, nodes, resistors);
}

/*
 *-------------------------------------------------------------------------
 *
 * Write the nodename to the output.  If the name does not exist, the node
 * ID number is used as the name.  Assumes that node has either a valid
 * name or valid ID record.
 *
 *-------------------------------------------------------------------------
 */

void
resWriteNodeName(fp, nodeptr)
   FILE		*fp;
   resNode	*nodeptr;
{
    if (nodeptr->rn_name == NULL)
	fprintf(fp, "N%d", nodeptr->rn_id);
    else
	fprintf(fp, "N%s", nodeptr->rn_name);
}

/*
 *-------------------------------------------------------------------------
 *
 * Write a description of the resistor network geometry, compatible
 * with FastHenry (mainly for doing inductance extraction)
 *
 *-------------------------------------------------------------------------
 */

void
ResPrintFHNodes(fp, nodelist, nodename, nidx, celldef)
    FILE	*fp;
    resNode	*nodelist;
    char	*nodename;
    int		*nidx;
    CellDef	*celldef;
{
    char 	newname[16];
    resNode	*nodeptr;
    resResistor	*resptr, *contact_res;
    resElement	*elemptr;
    float	oscale, height;
    int		np;

    if (fp == NULL) return;

    oscale = CIFGetOutputScale(1000);   /* 1000 for conversion to um */

    fprintf(fp, "\n* List of nodes in network\n");
    for (nodeptr = nodelist; nodeptr; nodeptr = nodeptr->rn_more)
    {
	if (nodeptr->rn_name == NULL)
	{
	    nodeptr->rn_id = (*nidx);
	    (*nidx)++;
	}
	else
	{
	    HashEntry  *entry;
	    ResExtNode *extnode;

	    /* If we process another sim file node while doing this	*/
	    /* one, mark it as status "REDUNDANT" so we don't duplicate	*/
	    /* the entry.						*/

     	    entry = HashFind(&ResNodeTable, nodeptr->rn_name);
	    extnode = (ResExtNode *)HashGetValue(entry);
	    if (extnode != NULL)
		extnode->status |= REDUNDANT;
	}
	resWriteNodeName(fp, nodeptr);

	/* Height of the layer is the height of the first non-contact   */
	/* layer type connected to any resistor connected to this node.	*/

	contact_res = (resResistor *)NULL;
	for (elemptr = nodeptr->rn_re; elemptr; elemptr = elemptr->re_nextEl)
	{
	    resptr = elemptr->re_thisEl;
	    if (!DBIsContact(resptr->rr_tt))
	    {
		height = ExtCurStyle->exts_height[resptr->rr_tt];
		if (height == 0)
		{
		    int pnum = DBPlane(resptr->rr_tt);
		    int hnum = ExtCurStyle->exts_planeOrder[pnum];
		    height = 0.1 * hnum;
		}
	    }
	    else
		contact_res = resptr;
	}
	height *= oscale;

	fprintf(fp, " x=%1.2f y=%1.2f z=%1.2f\n",
		(float)nodeptr->rn_loc.p_x * oscale,
		(float)nodeptr->rn_loc.p_y * oscale,
		height);

	/* If it's a contact region and has more than one contact, add	*/
	/* contact points as individual nodes and connect to the main 	*/
	/* node with an "equiv" record.					*/

	if (contact_res != (resResistor *)NULL &&
		(contact_res->rr_cl > 1 ||
		contact_res->rr_width > 1))
	{
	    int i, j, edge, spacing;
	    float del, cx, cy, cxb, cyb;

	    CIFGetContactSize(contact_res->rr_tt, &edge, &spacing, NULL);

	    del = (float)(spacing + edge) / (oscale * 100);

	    cxb = (float)(contact_res->rr_cl - 1) / 2;
	    for (i = 0; i < contact_res->rr_cl; i++)
	    {
		cx = del * ((float)i - cxb);
	        cyb = (float)(contact_res->rr_width - 1) / 2;
		for (j = 0; j < contact_res->rr_width; j++)
		{
		    cy = del * ((float)j - cyb);
		    resWriteNodeName(fp, nodeptr);
		    fprintf(fp, "_%d_%d ", i, j);
		    fprintf(fp, "x=%1.2f y=%1.2f z=%1.2f\n",
			((float)nodeptr->rn_loc.p_x + cx) * oscale,
			((float)nodeptr->rn_loc.p_y + cy) * oscale,
			height);
		}
	    }

	    /* Short all the contact nodes together with .equiv records */

	    fprintf(fp, ".equiv ");
	    resWriteNodeName(fp, nodeptr);
	    for (i = 0; i < contact_res->rr_cl; i++)
	    {
		for (j = 0; j < contact_res->rr_width; j++)
		{
		    fprintf(fp, " ");
		    resWriteNodeName(fp, nodeptr);
		    fprintf(fp, "_%d_%d", i, j);
		}
	    }
	    fprintf(fp, "\n");
	}
    }

    fprintf(fp, "\n* List of externally-connected ports\n.external");
    np = 0;
    for (nodeptr = nodelist; nodeptr; nodeptr = nodeptr->rn_more)
    {
	if (nodeptr->rn_name != NULL)
	{
	    if (np < 2)
	    {
		Label *lab;

		fprintf(fp, " N%s", nodeptr->rn_name);

		/* This part is sort of a hack---need a better hook to	*/
		/* the original label this external port connects to,	*/
		/* rather than search for it every time we write an	*/
		/* external connection.					*/

		for (lab = celldef->cd_labels; lab != NULL; lab = lab->lab_next)
		    if (lab->lab_flags & PORT_DIR_MASK)
			if (!strcmp(lab->lab_text, nodeptr->rn_name))
			{
			    if (lab->lab_port != ResPortIndex)
			    {
				lab->lab_port = ResPortIndex;
				TxPrintf("Port %s reassigned index %d\n",
					lab->lab_text, lab->lab_port);
				celldef->cd_flags |= (CDMODIFIED | CDGETNEWSTAMP);
			    }
			    ResPortIndex++;
			}
	    }
	    else
	    {
		if (np == 2)
		    fprintf(fp, "\n* Warning! external nodes not recorded:");
		fprintf(fp, " N%s", nodeptr->rn_name);
	    }
	    np++;
	}
    }
    fprintf(fp, "\n\n");

    /* Shouldn't this work? */

/*
    fprintf(fp, "\n* List of externally-connected ports\n");
    for (nodeptr = nodelist; nodeptr; nodeptr = nodeptr->rn_more)
	if (nodeptr->rn_name != NULL)
	    fprintf(fp, ".external N%s Nsub\n", nodeptr->rn_name);

    fprintf(fp, "\n");
*/
}

/*
 *-------------------------------------------------------------------------
 * ResPrintFHRects --
 *	Generate FastHenry segment output to the FastHenry data file
 *	"fp".
 *
 * Results:
 *	None.
 *
 * Side effects:
 *	Stuff written to the stream file "fp".
 *
 *-------------------------------------------------------------------------
 */

void
ResPrintFHRects(fp, reslist, nodename, eidx)
    FILE	*fp;
    resResistor	*reslist;
    char	*nodename;
    int		*eidx;		/* element (segment) index */
{
    resResistor	*resistors;
    float	oscale, thick, cwidth;
    int		edge;

    if (fp == NULL) return;

    oscale = CIFGetOutputScale(1000);   /* 1000 for conversion to um */

    fprintf(fp, "* Segments connecting nodes in network\n");
    for (resistors = reslist; resistors; resistors = resistors->rr_nextResistor)
    {
	if (DBIsContact(resistors->rr_tt) &&
		(resistors->rr_cl > 1 || resistors->rr_width > 1))
	{
	    int i, j;

	    CIFGetContactSize(resistors->rr_tt, &edge, NULL, NULL);

	    /* 100 is for centimicrons to microns conversion */
	    cwidth = (float)edge / 100;

	    /* for contacts, rr_cl = squares in x, rr_width = squares in y */

	    for (i = 0; i < resistors->rr_cl; i++)
	    {
		for (j = 0; j < resistors->rr_width; j++)
		{
		    fprintf(fp, "E%d ", *eidx);
		    resWriteNodeName(fp, resistors->rr_connection1);
		    fprintf(fp, "_%d_%d ", i, j);
		    resWriteNodeName(fp, resistors->rr_connection2);
		    fprintf(fp, "_%d_%d ", i, j);

		    /* Vias are vertical and so w and h are the dimensions of	*/
		    /* the via hole.  For other layers, h is layer thickness.	*/

		    fprintf(fp, "w=%1.2f h=%1.2f\n", cwidth, cwidth);

		    (*eidx)++;
		}
	    }
	}
	else
	{
	    fprintf(fp, "E%d ", *eidx);
	    resWriteNodeName(fp, resistors->rr_connection1);
	    fprintf(fp, " ");
	    resWriteNodeName(fp, resistors->rr_connection2);

	    if (DBIsContact(resistors->rr_tt))
	    {
		CIFGetContactSize(resistors->rr_tt, &edge, NULL, NULL);
		/* 100 for centimicrons to microns conversion */
		cwidth = (float)edge / 100;
		fprintf(fp, " w=%1.2f h=%1.2f\n", cwidth, cwidth);
	    }
	    else
	    {
		/* For non-via layers, h is layer thickness. */

		thick = ExtCurStyle->exts_thick[resistors->rr_tt];
		if (thick == 0) thick = 0.05;
		fprintf(fp, " w=%1.2f h=%1.2f\n",
			(float)resistors->rr_width * oscale,
			thick * oscale);

	    }
	    (*eidx)++;
	}
    }
}

/*
 *-------------------------------------------------------------------------
 *
 * ResPrintReference --
 *
 *	Write the reference plane (substrate) definition to the geometry
 *	(FastHenry) file output.
 *
 *	NOTE:  For now, I am assuming that substrate = ground (GND).
 *	However, a device list is passed, and it should be parsed
 *	for substrate devices, allowing the creation of VDD and GND
 *	reference planes for both substrate and wells.
 *
 *	Another note:  For now, I am assuming a uniform reference
 *	plane of the size of the cell bounding box.  It may be
 *	preferable to search tiles and generate multiple, connected
 *	reference planes.  Or it may be desirable to have an effectively
 *	infinite reference plane by extending it far out from the
 *	subcircuit bounding box.
 *
 *-------------------------------------------------------------------------
 */

void
ResPrintReference(fp, devices, cellDef)
    FILE	*fp;
    RDev	*devices;
    CellDef	*cellDef;
{
    char 	*outfile = cellDef->cd_name;
    Rect	*bbox = &(cellDef->cd_bbox);
    int		numsegsx, numsegsy;
    float	oscale, llx, lly, urx, ury;

    oscale = CIFGetOutputScale(1000);   /* 1000 for conversion to um */
    llx = (float)bbox->r_xbot * oscale;
    lly = (float)bbox->r_ybot * oscale;
    urx = (float)bbox->r_xtop * oscale;
    ury = (float)bbox->r_ytop * oscale;

    fprintf(fp, "* FastHenry output for magic cell %s\n\n", outfile);
    fprintf(fp, ".Units um\n");
    fprintf(fp, ".Default rho=0.02 nhinc=3 nwinc=3 rh=2 rw=2\n\n");
    fprintf(fp, "* Reference plane (substrate, ground)\n");

    fprintf(fp, "Gsub x1=%1.2f y1=%1.2f z1=0 x2=%1.2f y2=%1.2f z2=0\n",
		llx, lly, urx, lly);
    fprintf(fp, "+ x3=%1.2f y3=%1.2f z3=0\n", urx, ury);

    /* Grid the reference plane at 20 lambda intervals.  This	*/
    /* may warrant a more rigorous treatment.  20 is arbitrary.	*/
    /* Minimum number of segments is 4 (also arbitrary).	*/

    numsegsx = (bbox->r_xtop - bbox->r_xbot) / 20;
    numsegsy = (bbox->r_ytop - bbox->r_ybot) / 20;
    if (numsegsx < 4) numsegsx = 4;
    if (numsegsy < 4) numsegsy = 4;

    fprintf(fp, "+ thick=0.1 seg1=%d seg2=%d\n", numsegsx, numsegsy);

    fprintf(fp, "+ Ngp (%1.2f,%1.2f,0)\n", llx, lly);

    fprintf(fp, "\nNsub x=%1.2f y=%1.2f z=0\n", llx, lly);
    fprintf(fp, ".Equiv Nsub Ngp\n");
}

/*
 *-------------------------------------------------------------------------
 * ResCreateCenterlines --
 *	Generate centerline markers on the layout that correspond to
 * 	network routes.  Use the "DBWelement" mechanism.
 *
 * Results:
 *	0 on success, -1 if a window cannot be found.
 *
 * Side effects:
 *	Database "line" elements are generated in the layout.
 *
 *-------------------------------------------------------------------------
 */

int
ResCreateCenterlines(reslist, nidx, def)
    resResistor	*reslist;
    int		*nidx;
    CellDef *def;
{
    resResistor	*resistors;
    resNode *nodeptr;
    Rect r, rcanon;
    MagWindow *w;	/* should be passed from up in CmdExtResis. . . */
    char name[128];

    w = ToolGetBoxWindow (&r,  (int *)NULL);
    if (w == (MagWindow *)NULL)
	windCheckOnlyWindow(&w, DBWclientID);
    if ((w == (MagWindow *) NULL) || (w->w_client != DBWclientID)) {
        TxError("Put the cursor in a layout window.\n");
        return -1;
    }

    for (resistors = reslist; resistors; resistors = resistors->rr_nextResistor)
    {
	/* Ignore vias */

	if (!DBIsContact(resistors->rr_tt))
	{
	    nodeptr = resistors->rr_connection1;
	    r.r_xbot = nodeptr->rn_loc.p_x;
	    r.r_ybot = nodeptr->rn_loc.p_y;
	    if (nodeptr->rn_name == NULL)
	    {
		nodeptr->rn_id = (*nidx);
		(*nidx)++;
		sprintf(name, "N%d_", nodeptr->rn_id);
	    }
	    else
		sprintf(name, "N%s_", nodeptr->rn_name);

	    nodeptr = resistors->rr_connection2;
	    r.r_xtop = nodeptr->rn_loc.p_x;
	    r.r_ytop = nodeptr->rn_loc.p_y;
	    GeoCanonicalRect(&r, &rcanon);
	    if (nodeptr->rn_name == NULL)
	    {
		nodeptr->rn_id = (*nidx);
		(*nidx)++;
		sprintf(name + strlen(name), "%d", nodeptr->rn_id);
	    }
	    else
		strcat(name, nodeptr->rn_name);

	    /* Note that if any element exists with name "name"	*/
	    /* it will be deleted (overwritten).		*/
	    DBWElementAddLine(w, name, &rcanon, def, STYLE_YELLOW1);
	}
    }
    return 0;
}
